package mx.com.mesaregia.cotizaciones.integration.event; import mx.com.mesaregia.cotizaciones.integration.client.InternalRestClientFactory; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; @Component public class SecurityAuditRestClient {private final RestClient client;public SecurityAuditRestClient(InternalRestClientFactory f){client=f.create(System.getenv().getOrDefault("MR_SEGURIDAD_BASE_URL","http://localhost:8081"));}public void send(String accion,String id,String detalle,String corr){client.post().uri("/internal/v1/auditoria").body(new Req("COTIZACIONES",accion,"COTIZACION",id,null,detalle,corr)).retrieve().toBodilessEntity();}private record Req(String modulo,String accion,String tipoRecurso,String identificadorRecurso,String motivo,String detalle,String correlationId){}}
